pub const CONTENT_TYPE:&str="application/vnd.aurora.worldgen.typed-determinism-contract-receipt+json";
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]
pub struct DeterminismContractRequest{pub request_id:String,pub consumer:String,pub producer:String,pub namespace:String,pub semantic_profile:String,pub negotiated_version:String,pub field_order:Vec<String>,pub retained_field_order:Vec<String>,pub missing_field_order:Vec<String>,pub replay_identity:ContentHash,pub policy_allow:bool,pub protected_closure:bool,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]
pub struct DeterminismContractReceipt{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub request_id:String,pub consumer:String,pub producer:String,pub namespace:String,pub semantic_profile:String,pub negotiated_version:String,pub compatibility:String,pub disposition:String,pub field_order:Vec<String>,pub retained_field_order:Vec<String>,pub missing_field_order:Vec<String>,pub omitted_field_order:Vec<String>,pub semantic_loss_order:Vec<String>,pub replay_identity:ContentHash,pub contract_digest:ContentHash,pub effect_receipts:Vec<String>,pub artifact:serde_json::Value,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
#[derive(Debug,Error,Clone,PartialEq,Eq)]pub enum DeterminismContractError{#[error("invalid determinism contract request: {0}")]Invalid(String),#[error("invalid determinism contract receipt: {0}")]Receipt(String),#[error("determinism contract artifact failed: {0}")]Artifact(String)}
fn h(v:&ContentHash)->bool{v.as_str().len()==64&&v.as_str().bytes().all(|b|b.is_ascii_hexdigit())}fn o(v:&[String])->bool{v.windows(2).all(|p|p[0]<p[1])}
impl DeterminismContractReceipt{pub fn validate(&self)->Result<(),DeterminismContractError>{if self.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||self.boundary!=PRECLINICAL_BOUNDARY||self.artifact.get("boundary").and_then(|v|v.as_str())!=Some(PRECLINICAL_BOUNDARY)||self.artifact.get("content_type").and_then(|v|v.as_str())!=Some(CONTENT_TYPE)||!self.raw_data_local||!self.aggregate_only||self.field_order.is_empty()||![&self.replay_identity,&self.contract_digest].into_iter().all(h){return Err(DeterminismContractError::Receipt("determinism contract identity or digest is incomplete".into()));}for v in [&self.field_order,&self.retained_field_order,&self.missing_field_order,&self.omitted_field_order,&self.semantic_loss_order,&self.effect_receipts]{if !o(v){return Err(DeterminismContractError::Receipt("determinism contract vectors are not canonical".into()));}}let f=self.field_order.iter().cloned().collect::<BTreeSet<_>>();let p=self.retained_field_order.iter().chain(&self.missing_field_order).chain(&self.omitted_field_order).cloned().collect::<BTreeSet<_>>();if f!=p{return Err(DeterminismContractError::Receipt("determinism fields do not partition".into()));}Ok(())}}
pub fn manifest(feature_id:&str,version:&str,scale:&str)->serde_json::Value{json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":feature_id,"version":version,"owner_crate":"worldgen","consumers":["imaging core scientist","research program lead","developer"],"behavior":format!("negotiate typed statistical-causal-ML determinism contract for {scale}"),"value":"makes determinism schema compatibility, semantic loss, locality, and permissions explicit","input_schema":"DeterminismContractRequest1@1","output_schema":"DeterminismContractReceipt1@1","effects":["none:determinism-contract-validation","block:unsafe-determinism"],"permissions":["negotiate:determinism-contract"],"determinism":"byte_stable","autonomy_tier":"A1","boundary":PRECLINICAL_BOUNDARY})}
pub fn negotiate(r:&DeterminismContractRequest,feature_id:&str,version:&str,_scale:&str,_federation:bool)->Result<DeterminismContractReceipt,DeterminismContractError>{if r.request_id.trim().is_empty()||r.field_order.is_empty()||r.boundary!=PRECLINICAL_BOUNDARY||!r.raw_data_local||!r.aggregate_only||!h(&r.replay_identity){return Err(DeterminismContractError::Invalid("determinism contract request is invalid".into()))}let fields=r.field_order.iter().cloned().collect::<BTreeSet<_>>();let retained=r.retained_field_order.iter().filter(|x|fields.contains(*x)).cloned().collect::<BTreeSet<_>>();let missing=fields.difference(&retained).cloned().collect::<BTreeSet<_>>();let omitted=r.missing_field_order.iter().filter(|x|fields.contains(*x)).cloned().collect::<BTreeSet<_>>();let disposition=if !r.policy_allow||!r.protected_closure{"blocked"}else if missing.is_empty()&&omitted.is_empty(){"compatible"}else if retained.is_empty(){"unknown"}else{"partial"};let payload=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":version,"feature_id":feature_id,"request_id":r.request_id,"consumer":r.consumer,"producer":r.producer,"namespace":r.namespace,"semantic_profile":r.semantic_profile,"negotiated_version":r.negotiated_version,"compatibility":if disposition=="compatible"{"compatible"}else{"additive_migration"},"disposition":disposition,"field_order":fields,"retained_field_order":retained,"missing_field_order":missing,"omitted_field_order":omitted,"semantic_loss_order":Vec::<String>::new(),"replay_identity":r.replay_identity,"effect_receipts":vec!["none:determinism-contract-validation"],"raw_data_local":true,"aggregate_only":true,"boundary":PRECLINICAL_BOUNDARY});let d=ContentHash::of_value(&payload).map_err(|e|DeterminismContractError::Artifact(e.to_string()))?;let out=DeterminismContractReceipt{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:version.into(),feature_id:feature_id.into(),request_id:r.request_id.clone(),consumer:r.consumer.clone(),producer:r.producer.clone(),namespace:r.namespace.clone(),semantic_profile:r.semantic_profile.clone(),negotiated_version:r.negotiated_version.clone(),compatibility:if disposition=="compatible"{"compatible"}else{"additive_migration"}.into(),disposition:disposition.into(),field_order:payload["field_order"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect(),retained_field_order:payload["retained_field_order"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect(),missing_field_order:payload["missing_field_order"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect(),omitted_field_order:payload["omitted_field_order"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect(),semantic_loss_order:vec![],replay_identity:r.replay_identity.clone(),contract_digest:d.clone(),effect_receipts:vec!["none:determinism-contract-validation".into()],artifact:json!({"content_type":CONTENT_TYPE,"content_hash":d,"boundary":PRECLINICAL_BOUNDARY}),raw_data_local:true,aggregate_only:true,boundary:PRECLINICAL_BOUNDARY.into()};out.validate()?;Ok(out)}
